configuration.jsScript:
var edgeConf = Number(msg.edge_conf || 0);
var gpuConf  = Number(msg.gpu_conf || 0);
var fusedConf = 0.4 * edgeConf + 0.6 * gpuConf;
msg.fused_conf = Math.round(fusedConf * 1000) / 1000;

if (msg.sos_triggered === true) {
    msg.alarm_type = 'CRITICAL_SOS_EMERGENCY';
    msg.alarm_severity = 'CRITICAL';
    msg.telegram_text = '[SOS EMERGENCY] Physical SOS button held on Node 2! Room Temp: ' + msg.room_temp_c + 'C.';
    return {msg: msg, metadata: metadata, msgType: msgType};
}

if (msg.csi_state === 'FALL' && fusedConf >= Number(msg.fall_threshold || 0.85)) {
    msg.alarm_type = 'CRITICAL_FALL_EMERGENCY';
    msg.alarm_severity = 'CRITICAL';
    msg.telegram_text = '[FALL EMERGENCY] Indoor fall detected! Fused AI Confidence: ' + Math.round(fusedConf * 100) + '%, Room Temp: ' + msg.room_temp_c + 'C. Please check immediately!';
    return {msg: msg, metadata: metadata, msgType: msgType};
}

if (msg.csi_state === 'WALKING' && msg.ble_authorized === false) {
    msg.alarm_type = 'MAJOR_INTRUSION_ALERT';
    msg.alarm_severity = 'MAJOR';
    msg.telegram_text = '[SECURITY ALERT] Unauthorized walking motion detected with NO valid resident BLE beacon!';
    return {msg: msg, metadata: metadata, msgType: msgType};
}

msg.alarm_type = 'NORMAL';
return {msg: msg, metadata: metadata, msgType: msgType};

configuration.alarmDetailsBuildJs:
var details = {};
details.alarm_type = msg.alarm_type;
details.fused_conf = msg.fused_conf;
details.ble_mac = msg.ble_mac;
details.telegram_text = msg.telegram_text;
return details;
